145 |         let mut sorted = true;
146 |         let mut min = u64::MAX;
147 |         let mut max = 0;
148 |         let mut count = 0;
149 | 
150 |         for val in values {
151 |             count += 1;
152 |             if val < min {
153 |                 min = val;
154 |             }
155 |             if val > max {
156 |                 max = val;
157 |             }
